import {valuesStories,valueSteps,normalizeValueProgress,refugeArabic,refugeMeaning} from './values-stories.js';
import {valueScene,valueObject} from './values-scenes.js';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,attributes='',kind='')=>'<button class="btn '+kind+'" data-action="stages-value-story-'+action+'" '+attributes+'>'+label+'</button>';
const pause=()=>'<button class="btn story-pause" data-action="stages-pause" disabled aria-pressed="false">Pause</button>';
const arabic=()=>'<div class="refuge-phrase"><p lang="ar" dir="rtl">'+refugeArabic+'</p><p lang="bn">'+refugeMeaning+'</p>'+btn('Listen & repeat Arabic','refuge')+btn('Stop','stop')+'<small>Listen together. This phrase is never scored.</small></div>';
export function createValueStoryFlow({getProgress,save,isSaved,render,status,play,stop}){
 let selected=null;
 const state=()=>getProgress(),story=()=>valuesStories.find(s=>s.id===selected),progress=()=>state().valueStories[selected],step=()=>valueSteps(story())[progress().step];
 const speak=parts=>{status('Listening…');play(parts);};
 function sentenceParts(line,paragraph=false){const s=story();return s.id==='values-brother-friend'&&line===2?[{key:'value-refuge-prefix',target:paragraph?'.story-line[data-line="2"]':'.story-sentence'},{key:'value-refuge-arabic',target:'.refuge-phrase [lang="ar"]'}]:[{key:'text:'+s.sentences[line],line:paragraph?line:undefined}];}
 function known(v){return progress().wordsMet.includes(v.word.toLowerCase())||state().valueWordsMet.includes(v.word.toLowerCase())||state().storyWordsMet.includes(v.word.toLowerCase())||Object.entries(state().words).some(([id,p])=>p.done&&id==='first-'+v.word.toLowerCase());}
 function advance(){const p=progress();stop();if(!p.completed.includes(p.step))p.completed.push(p.step);p.step=Math.min(valueSteps(story()).length-1,p.step+1);p.blank=0;save();render();}
 function question(){const st=step(),p=progress();if(st.type==='paragraph-gaps')return {...story().questions[p.blank],id:'paragraph-'+story().questions[p.blank].id};return st.q;}
 function attempt(q){return progress().attempts[q.id];}
 function complete(q){return progress().answers[q.id]===q.word;}
 function sentence(line,q,filled=false){const s=story();let t=esc(s.sentences[line]);if(q)t=t.replace(new RegExp('\\b'+q.word+'\\b'),'\u0000').replace('\u0000','<span class="paragraph-blank '+(filled?'filled':'current')+'">'+(filled?esc(q.word):'_____')+'</span>');return '<p class="story-sentence" lang="en">'+t+'</p>';}
 function paragraph(gaps=false){const s=story(),p=progress();return '<div class="story-paragraph" aria-label="Story paragraph">'+s.sentences.map((text,line)=>{let t=esc(text);if(gaps)s.questions.forEach((q,i)=>{if(q.line===line){const id='paragraph-'+q.id,filled=p.answers[id]===q.word;t=t.replace(new RegExp('\\b'+q.word+'\\b'),'<span class="paragraph-blank '+(filled?'filled':i===p.blank?'current':'')+'">'+(filled?esc(q.word):'_____')+'</span>');}});return '<span class="story-line" data-line="'+line+'">'+t+'</span>';}).join(' ')+'</div>';}
 function choices(q){const p=progress(),a=attempt(q),correct=complete(q),choices=a.easier?q.choices.filter(w=>w===q.word||w===q.choices.find(w=>w!==q.word)):q.choices;
  if(correct)return '<p class="story-feedback" role="status">✓ '+(q.type==='listen'?'You found the picture.':'Read the completed sentence aloud.')+'</p>';
  if(a.helpOpen)return '<div class="story-demonstration"><p class="story-sentence">'+esc(story().sentences[q.line])+'</p><p class="story-gap-hint">'+esc(q.hint)+'</p><div class="story-controls">'+btn('Replay demonstration','demonstrate')+pause()+btn('Try with help →','retry','','primary')+'</div></div>';
  return '<div class="story-answer-choices">'+choices.map(w=>'<button class="choice word-choice '+(p.answers[q.id]===w?'retry':'')+'" data-action="stages-value-story-answer" data-word="'+esc(w)+'">'+(q.type==='listen'?valueObject(w):esc(w))+'</button>').join('')+'</div><p class="story-feedback story-gap-hint" role="status">'+(a.wrong?esc(q.hint):a.easier?'Try again with two choices.':'Choose one answer.')+'</p>'+(a.wrong?'<div class="story-listen">'+btn('Hear hint','hint')+pause()+'</div>':'');
 }
 function footer(){const s=story();return '<div class="value-story-extras"><details class="story-parents"><summary>For parents · ঐচ্ছিক আলোচনা ও শিক্ষা</summary><div class="value-lesson-note"><b lang="bn">শিক্ষা</b><p lang="bn">'+esc(s.note)+'</p><div class="story-controls">'+btn('গল্পের শিক্ষা শুনি','note','lang="bn"')+btn('Replay','note')+btn('Stop','stop')+'</div></div><p lang="bn">'+esc(s.question)+'</p><p lang="bn"><b>সম্ভাব্য উত্তর:</b> '+esc(s.answer)+'</p><p>This is original fiction about Islamic values. It is not a quotation from hadith. A star records practice, not independent reading mastery.</p>'+(s.id==='values-dua-mum'?'<p>The English dua is the child’s own prayer, not a prescribed quotation.</p>':'')+s.references.map(r=>'<p lang="bn">'+esc(r.note)+' <a href="'+r.url+'" target="_blank" rel="noopener">'+esc(r.label)+'</a></p>').join('')+(s.id==='values-brother-friend'?'<p>Arabic audio: <a href="https://islamicbulletin.org/?page_id=45#" target="_blank" rel="noopener">The Islamic Bulletin, “Upon Getting Angry”</a>. Whole-phrase highlighting; no word timestamps.</p>':'')+'</details></div>';}
 function html(){const s=story(),p=progress(),st=step();let heading='',body='',canNext=true;
  if(st.type==='vocabulary'){
   const v=s.vocabulary[p.vocab],learned=known(v);heading='Words & meanings · '+(p.vocab+1)+' of '+s.vocabulary.length;
   body='<details class="value-readiness"><summary>Assisted reading · sounds & words to review</summary><p>'+esc(s.demand)+'</p><p>Use English audio and read with an adult. Knowing a Bengali meaning does not show that a word can be decoded independently.</p></details><p class="story-helper-word value-vocab-word" lang="en">'+esc(v.word)+'</p><p class="story-helper-meaning" lang="bn">'+esc(v.meaning)+'</p>'+(v.kind==='object'?valueObject(v.object):v.kind==='action'?valueScene(s,v.line):'')+'<p class="value-context" lang="en">'+esc(v.example)+'</p><p class="muted">'+(learned?'Reviewed before · review is optional.':'Listen, look and read together.')+'</p><div class="story-listen">'+btn('Hear word · Replay','word')+pause()+'</div><div class="story-controls">'+btn('← Previous word','vocab-prev',p.vocab===0?'disabled':'')+btn(p.vocab+1<s.vocabulary.length?'Next word →':'Start story →','vocab-next','','primary')+'</div>'+btn(p.review?'Return to reading':'Skip to story','skip','','quiet story-skip');canNext=false;
  }else if(st.type==='sentence'){
   heading='Sentence '+(st.line+1)+' of '+s.sentences.length;body=valueScene(s,st.line)+sentence(st.line)+(s.id==='values-brother-friend'&&st.line===2?arabic():'')+'<div class="story-listen">'+btn('Hear sentence · Replay','sentence-audio')+pause()+'</div>';
  }else if(st.type==='sentence-gap'||st.type==='paragraph-gaps'||st.type==='play'){
   const q=question(),a=attempt(q),correct=complete(q);heading=st.type==='play'?'Let’s play · '+(st.index+1)+' of 3':st.type==='paragraph-gaps'?'Paragraph · blank '+(p.blank+1)+' of 2':'Picture sentence · '+(st.index+1)+' of 2';
   const recall=q.type==='recall';body='<p class="blank-prompt">'+(q.type==='listen'?'Hear a taught word. Choose its picture.':recall?'Which word was in the story?':'Look at the picture. Choose the missing word.')+'</p>'+(q.type==='listen'?'<div class="story-listen">'+btn('Hear word · Replay','play-word')+pause()+'</div>':valueScene(s,q.line))+(st.type==='paragraph-gaps'?paragraph(true):q.type==='listen'?'':sentence(q.line,q,correct));
   if(recall)body+='<div class="story-listen">'+btn('Hear story sentence · Replay','sentence-audio')+pause()+'</div>';
   body+=choices(q);canNext=correct;
  }else if(st.type==='complete'){
   heading='Your complete story';body=paragraph()+(s.id==='values-brother-friend'?arabic():'')+'<div class="story-listen">'+btn('Hear paragraph · Replay','paragraph-audio')+pause()+'</div><p class="story-feedback">Read together or try reading aloud. Audio is optional.</p>';
  }else{
   heading='Story practice complete';body='<div class="value-star" role="img" aria-label="One completion star">'+(p.star?'★':'☆')+'</div><p class="story-feedback">'+(p.star?'You practised this story!':'Tap to mark this practice complete.')+'</p><p class="muted">'+(p.assisted?'Completed with help. ':'')+'A star records practice, not independent reading mastery.</p><div class="story-controls">'+(p.star?'<button class="btn primary" data-action="stages-story-back">Return to Stories →</button>':btn('I practised this story ★','finish','','primary'))+'</div>';canNext=false;
  }
  if(st.type!=='vocabulary')body+='<div class="story-controls">'+btn('← Previous','previous',p.step===0?'disabled':'')+(canNext?btn('Next →','next','','primary'):'')+'</div>';
  return '<section class="activity story-player value-player" data-phase="'+st.type+'" data-story="'+s.id+'"><div class="story-player-heading"><p class="eyebrow">'+heading+'</p><h1>'+esc(s.title)+'</h1></div>'+body+'<p class="value-assisted-label">Read with an adult · audio is optional</p><div class="value-review">'+btn('Review words','review')+btn('← Stories','home')+'</div><p class="story-save" id="save-status">'+(isSaved()?'Saved automatically':'Progress not saved')+'</p><p id="audio-status" class="status" role="status"></p></section>'+footer();
 }
 function demonstrate(q){speak([...sentenceParts(q.line),{key:'story-hint:'+q.hint,target:'.story-gap-hint'}]);}
 return {html,open(id){stop();selected=id;const s=story();if(!s)return;state().valueCurrent=id;state().valueStories[id]??=normalizeValueProgress({},s);const p=progress();if(p.step===0&&!p.review){const first=s.vocabulary.findIndex(v=>!known(v));if(first<0)p.step=1;else if(known(s.vocabulary[p.vocab]))p.vocab=first;}save();render();},handle(data){const s=story(),p=progress(),st=step();if(!s||!p)return;const action=data.action.replace('stages-value-story-','');
  if(action==='stop'){stop();return;}
  if(action==='word'&&st.type==='vocabulary'){const v=s.vocabulary[p.vocab];speak([{key:'value-word:'+v.word,target:'.value-vocab-word'}]);}
  else if(action==='vocab-prev'&&st.type==='vocabulary'&&p.vocab>0){stop();p.vocab--;save();render();}
  else if(action==='vocab-next'&&st.type==='vocabulary'){const v=s.vocabulary[p.vocab],word=v.word.toLowerCase();stop();if(!p.wordsMet.includes(word))p.wordsMet.push(word);if(!state().valueWordsMet.includes(word))state().valueWordsMet.push(word);const next=s.vocabulary.findIndex((v,i)=>i>p.vocab&&(p.review||!known(v)));if(next>=0){p.vocab=next;save();render();}else if(p.review){p.step=p.reviewReturn;p.review=false;save();render();}else advance();}
  else if(action==='skip'&&st.type==='vocabulary'){stop();p.step=p.review?p.reviewReturn:1;p.review=false;save();render();}
  else if(action==='review'){stop();p.reviewReturn=p.step;p.step=0;p.review=true;p.vocab=0;save();render();}
  else if(action==='previous'&&p.step>0){stop();p.step--;p.blank=0;save();render();}
  else if(action==='next'){if(['sentence-gap','paragraph-gaps','play'].includes(st.type)){const q=question();if(!complete(q))return;if(st.type==='paragraph-gaps'&&p.blank===0){stop();p.blank=1;save();render();return;}}advance();}
  else if(action==='sentence-audio'){const line=st.line??question()?.line;if(line!==undefined)speak(sentenceParts(line));}
  else if(action==='paragraph-audio'&&st.type==='complete')speak(s.sentences.flatMap((_,line)=>sentenceParts(line,true)));
  else if(action==='refuge'&&s.id==='values-brother-friend')speak([{key:'value-refuge-arabic',target:'.refuge-phrase [lang="ar"]'}]);
  else if(action==='note')speak([{key:'value-note:'+s.id,target:'.value-lesson-note p'}]);
  else if(action==='play-word'&&st.type==='play')speak([{key:'value-instruction:picture'},{key:'value-word:'+st.q.word}]);
  else if(action==='hint'){const q=question();speak([{key:'story-hint:'+q.hint,target:'.story-gap-hint'}]);}
  else if(action==='demonstrate')demonstrate(question());
  else if(action==='retry'){const q=question(),a=attempt(q);stop();a.helpOpen=false;a.easier=true;a.assisted=true;p.assisted=true;p.answers[q.id]=null;save();render();speak([{key:'value-instruction:retry'}]);}
  else if(action==='answer'&&['sentence-gap','paragraph-gaps','play'].includes(st.type)){const q=question(),a=attempt(q);if(complete(q)||a.helpOpen||!q.choices.includes(data.word))return;stop();a.attempts++;if(a.firstChoice===null){a.firstChoice=data.word;a.firstCorrect=data.word===q.word;}p.answers[q.id]=data.word;if(data.word!==q.word){a.wrong++;a.assisted=true;p.assisted=true;if(a.wrong>=2){a.demonstrated=true;a.helpOpen=true;}save();render(false);if(a.helpOpen)demonstrate(q);else speak([{key:'story-hint:'+q.hint,target:'.story-gap-hint'}]);}else{save();render(false);speak([{key:'value-praise'},{key:'at-tone:success'}]);document.querySelector('.story-controls .primary')?.focus({preventScroll:true});}}
  else if(action==='finish'&&st.type==='finish'){stop();p.star=true;p.done=true;if(!p.completed.includes(p.step))p.completed.push(p.step);save();render(false);speak([{key:'value-praise'},{key:'at-tone:success'}]);}
 }};
}
